/**
 *  One of a work list's own fields: kept in an item's `native` under
 *  `name`, declared so screens render and edit it without knowing which
 *  list is active.
 */
export type FieldDecl = {
	// Its key in `native` (snake_case).
	name: string,
	// How a person names it.
	title: string,
	kind: FieldKind,
	/**
	 *  An `enum`'s values, in the order they're offered (empty for any
	 *  other kind).
	 */
	values?: string[],
	/**
	 *  Set by the list itself (who filed it, when it synced): shown, never
	 *  edited — a `oxplow.work_item.update` that names it is refused.
	 */
	read_only?: boolean,
};

// What kind of value a declared field holds.
export type FieldKind = 
// One of `values`.
"enum" | "text" | "number";

export type FileSnapshot = {
	id: number,
	stream_id: StreamId,
	path: string,
	/**
	 *  The storage ADDRESS: xxh3-128 (storage = oxplow) or git blob OID
	 *  (storage = git); NULL for oversize / deleted rows. Compare
	 *  [`Self::content_hash`], not this.
	 */
	blob_hash: string | null,
	size_bytes: number,
	captured_at: Timestamp,
	/**
	 *  Where the bytes live — see [`SnapshotStorage`]. Replaces the old
	 *  `oversize: bool` field; deletion tombstones are
	 *  `SnapshotStorage::Deleted`.
	 */
	storage: SnapshotStorage,
	/**
	 *  `snapshot.id` this row was captured under, or `None` for
	 *  pre-V13 rows that predate the snapshot grouping table.
	 */
	snapshot_id: number | null,
	/**
	 *  File mtime in unix milliseconds at capture time. NULL for
	 *  rows written before V15 added the column. The startup sweep
	 *  uses `(size_bytes, mtime_ms)` as a fast equality check: if
	 *  both match the current stat, the file is presumed unchanged
	 *  and the bytes aren't re-read or re-hashed.
	 */
	mtime_ms: number | null,
	/**
	 *  The content identity (V96): xxh3-128 of the bytes, whatever the
	 *  storage class. `blob_hash` is only the address. [`capture_batch`]
	 *  fills it from `blob_hash` for `oxplow` rows; `git` rows get it
	 *  lazily ([`SqliteSnapshotStore::with_content_hasher`]).
	 * 
	 *  [`capture_batch`]: SqliteSnapshotStore::capture_batch
	 */
	content_hash: string | null,
};

// How an effort came to own a file.
export type FileSource = 
// An edit tool named it.
"claimed" | 
/**
 *  It changed during one of the thread's turns and no other thread
 *  claimed it — a shell edit, a formatter, a generator.
 */
"observed";

// How a path differs from the head, or how a revision changed it.
export type FileStatus = "added" | "modified" | "deleted" | "renamed" | "untracked" | "conflicted";

/**
 *  A fact predicate on a `metrics:` spec (the `filter:` block) — the config
 *  mirror of the engine's `FactFilter`. A conjunctive predicate
 *  keeping only the facts that match before aggregation: `minValue` for a
 *  count-over-threshold (complexity ≥ N), `severity` for a lint slice, `dimEq`
 *  for a conformed-dimension slice (`[oxplow.rule, unsafe_block]`).
 */
export type FilterConfig = {
	// Keep facts with `value >= minValue`.
	minValue?: number | null,
	// Keep facts whose reported severity equals this (e.g. `error`).
	severity?: string | null,
	// Keep facts whose dimension `[key]` equals `[value]` — a 2-element list.
	dimEq?: string[] | null,
};

export type Followup = {
	id: string,
	thread_id: ThreadId,
	body: string,
	created_at: number,
};

/**
 *  An effect's or collector's `on:` naming an event type of another
 *  extension's namespace (P9.D1). The type's name is the dependency —
 *  there is no `depends:` key, as a model's `ref('<ext>/<name>')` has
 *  none: it resolves when an enabled extension registers the type.
 */
export type ForeignSubscription = {
	// What reacts: "effect `note`", "collector `pull`".
	by: string,
	eventType: string,
	// `file:line` of the declaration.
	declaredAt: string,
};

/**
 *  What a form lens shows: its command (the fields come from its input
 *  schema) and the values the fields start from — the form's `defaults`
 *  (placeholders bound) under the query's first row, if it has a query.
 */
export type FormStart = {
	command: CommandSpec,
	values: unknown,
};

/**
 *  A derived-metric formula on a `metrics:` spec (the `formula:` block) — a
 *  constrained binary op over two OTHER metric keys (no source measure). The
 *  engine aligns the two metrics on their shared rollup key and applies `op`
 *  (`div` is the ratio primitive: bugs-per-KLOC, cost-per-token).
 */
export type FormulaConfig = {
	// `add` | `sub` | `mul` | `div` (`ratio` aliases `div`).
	op: string,
	// The left operand metric key.
	left: string,
	// The right operand metric key.
	right: string,
};

/**
 *  What oxplow watches / snapshots / indexes, on top of the always-on
 *  `.git`/`.oxplow` ignores and the repo's `.gitignore`.
 * 
 *  - `exclude`: extra paths to ignore even when `.gitignore` doesn't
 *    (e.g. a tracked-but-noisy generated file).
 *  - `include`: gitignored paths to force back in (override
 *    `.gitignore` for something oxplow should still see).
 * 
 *  Each entry is a single segment (matches any path component —
 *  `target` matches every `target/`) or a repo-relative path (matches
 *  that path exactly or as a prefix — `apps/desktop/dist`).
 */
export type GeneratedConfig = {
	exclude?: string[],
	include?: string[],
};

// What a program may reach: what a person approves.
export type Grants = {
	entry: string,
	runtime: CollectorRuntime,
	args: string[],
	hosts: string[],
	credentials: string[],
	env: string[],
	// The scopes it may call (a provider's `needs`).
	scopes: string[],
};

// One registered harness, as the session picker and Settings see it.
export type HarnessListing = {
	// Its key (what `agents:` and a session's `harness` name).
	id: string,
	title: string,
	/**
	 *  It runs an ACP agent in a chat (a structured transcript), so a
	 *  session of it names one.
	 */
	chat: boolean,
	// The project enables it (`agents:` names it, or names none).
	enabled: boolean,
	// The settings it reads from its `agentConfig` entry.
	settings: HarnessSettingListing[],
};

// A harness setting, as Settings → Agents shows it.
export type HarnessSettingListing = {
	key: string,
	title: string,
	hint: string,
	placeholder: string,
};

// Where a stream's workspace is.
export type HeadInfo = {
	// The head revision; `None` before the first commit.
	revision: string | null,
	// The branch checked out; `None` when detached.
	branch: string | null,
};

/**
 *  What the hook subprocess sends us.
 * 
 *  The renderer / Claude Code emit JSON envelopes; the daemon receives
 *  them and lands them here. `payload_json` is the verbatim envelope
 *  minus the routing fields we hoist into typed columns.
 */
export type HookEnvelope = {
	kind: HookKind,
	thread_id: ThreadId | null,
	stream_id: StreamId | null,
	/**
	 *  The agent session it came from (`X-Oxplow-Session`, the ACP host,
	 *  the UI's interrupt), when the sender knows it.
	 */
	agent_session_id?: AgentSessionId | null,
	// The harness's own session id.
	session_id: string | null,
	payload_json: string,
	/**
	 *  UserPromptSubmit: the text the person submitted — stored with its
	 *  `agent.prompt.submitted` (every prompt, a re-prompt too) and on the
	 *  turn it opens.
	 */
	prompt: string | null,
	// PreToolUse only: the policy's verdict (`None` reads as allowed).
	decision?: ToolDecision | null,
};

/**
 *  Discriminant for hook events: the kinds the harnesses post, plus
 *  `Interrupt`, which oxplow synthesizes.
 */
export type HookKind = 
// Renderer/agent paste, run-command, etc.
"user_prompt_submit" | "pre_tool_use" | "post_tool_use" | "stop" | 
// Synthesized by oxplow when the user hits Ctrl-C / Esc in a pane.
"interrupt" | 
/**
 *  A harness process started or resumed a session (Claude's command
 *  hook, Codex's hook, the ACP client). `source: "compact"` is a
 *  compaction inside a running session, not a start.
 */
"session_start" | 
// A harness session ended — `reason: "clear"` for `/clear`.
"session_end" | 
/**
 *  The harness told the person something (Claude's `Notification`):
 *  a permission prompt waits on them.
 */
"notification" | 
// A subagent of the session started (Claude's `SubagentStart`).
"subagent_start" | 
/**
 *  A subagent of the session finished (Claude's `SubagentStop`, or a
 *  hand-back).
 */
"subagent_stop";

/**
 *  The host a stream's worktree is on. Every stream is on the local machine
 *  today ([`HostId::LOCAL`]); naming it keeps "local" from being assumed
 *  silently where a worktree path is reached (`WorktreeRoot::local_path`).
 */
export type HostId = string;

// Everything installing or updating an extension would change.
export type ImpactReport = {
	lenses: LensImpact[],
	models: ModelImpact[],
	collectors: CollectorImpact[],
	providers: ProviderImpact[],
	/**
	 *  Its effects: what each reacts to, and what each version
	 *  composes on the same events.
	 */
	effects: EffectImpact[],
	/**
	 *  What its dry runs didn't get to (`collector <id>`, `effect <id>`):
	 *  the review stops running scripts at its deadline.
	 */
	outOfTime: string[],
	/**
	 *  The report as lines ([`summary`]): what the install review, `extension
	 *  check --impact` and an effort's review say, in one wording.
	 */
	lines: string[],
};

// One implementation as the extension declares it.
export type ImplementationDecl = {
	capability: string,
	// What `activeProviders` names.
	id: string,
	// How a person names it; the built-in's own title when absent.
	title: string | null,
	/**
	 *  The built-in it is (`oxplow:tasks`); its features are core's to
	 *  say.
	 */
	entry: string,
	/**
	 *  The extension's skills (`skills:`) it owns: offered only while it's
	 *  the active implementation.
	 */
	skills: string[],
	/**
	 *  What the declaration configures, checked against the built-in's
	 *  schema; `{}` when it says nothing.
	 */
	config: any,
	/**
	 *  The scopes a policy script calls (`sql.read`); empty for anything
	 *  else.
	 */
	needs: string[],
};

// An operation paused mid-way, waiting on its conflicts.
export type InProgressOp = "merge" | "rebase" | "cherry_pick" | "revert";

export type InstalledLspPackage = {
	name: string,
	version: string,
	language_ids: string[],
	binary: string,
};

// One of an instance's credentials, as Settings → Integrations shows it.
export type InstanceCredential = {
	name: string,
	// This machine has a value for it (a signed-in one: a token).
	set: boolean,
	/**
	 *  For one the person signs in for, where that stands; none, its
	 *  value is pasted.
	 */
	signIn: SignInState | null,
	/**
	 *  For one signed in for at a service with its redirect port
	 *  registered (`redirect_port`): the loopback port the shell must
	 *  catch the redirect on. Any free port otherwise.
	 */
	redirectPort: number | null,
};

export type InstanceHealth = {
	state: InstanceState,
	// Its failures in a row (`contribution_health`'s count, shown here).
	consecutiveFailures: number,
	// RFC 3339.
	lastOkAt: string | null,
	// A moving average of its successful calls.
	meanInvokeMs: number | null,
	/**
	 *  The provider's service said to wait until then (RFC 3339): a rate
	 *  limit, which never counts as a failure. Cleared by the next
	 *  success.
	 */
	rateLimitedUntil: string | null,
	/**
	 *  What a read in progress last said (`$/progress`); `None` between
	 *  reads.
	 */
	activity: string | null,
};

// Where an instance stands on this machine.
export type InstanceState = 
// Not enabled in the project's config.
{ state: "off" } | 
/**
 *  Configured, but it names no provider an enabled extension
 *  declares; `reason` says what's wrong and how to fix it.
 */
{ state: "missing"; reason: string } | 
/**
 *  Enabled, but oxplow won't run it as configured: its id is a
 *  command namespace or provider something else already has, or it
 *  declares an event type oxplow doesn't know with that schema.
 *  `reason` says which (tsk840).
 */
{ state: "refused"; reason: string } | 
// Enabled, but this machine hasn't approved this version of it.
{ state: "unapproved" } | 
// Enabled, but its `check` found problems with its config.
{ state: "unconfigured"; problems: ConfigProblem[] } | 
// Being checked or started.
{ state: "checking" } | { state: "ready" } | 
// Its last start or call failed; it restarts with backoff.
{ state: "failing"; errors: string[] } | 
/**
 *  Stopped after repeated failures (or a handshake that didn't match
 *  its approved declarations), until a person enables it again.
 */
{ state: "disabled"; reason: string };

/**
 *  Why the extension exists — what makes it regenerable, repairable and
 *  reviewable against what it was for.
 */
export type Intent = {
	// The question it answers, or the job it does.
	purpose: string,
	// The thread or effort ref that created it (`effort:eff42`), when known.
	origin?: string | null,
	examples?: IntentExample[],
	/**
	 *  Questions it helps answer, offered to the person with an Ask
	 *  button (the catalog; pages for a ref of `about`'s kind).
	 */
	prompts?: IntentPrompt[],
};

/**
 *  One acceptance example: an input and what the extension should make
 *  of it. Fixtures for `oxplow extension test`; data here.
 */
export type IntentExample = {
	name: string,
	input?: unknown,
	expect?: unknown,
};

/**
 *  A question an extension helps answer. `about` is a ref kind
 *  (`commit`, `file`, `effort`): a page for a ref of that kind suggests it.
 */
export type IntentPrompt = {
	prompt: string,
	about?: string | null,
};

// Which surfaces may invoke a command.
export type Invokers = {
	human: boolean,
	agent: boolean,
	lens: boolean,
};

/**
 *  Frontend-facing error envelope.
 * 
 *  All command cores return `Result<T, IpcError>`, and the Tauri
 *  `#[tauri::command]` wrappers + the daemon's HTTP routes surface this
 *  same shape. Internal errors from the service layer are converted here
 *  so the JS side never has to reason about Rust-specific error types.
 */
export type IpcError = {
	code: string,
	message: string,
	cause: string | null,
};

export type ItemBody = 
/**
 *  What the human sent. `context` is the oxplow block attached to it,
 *  shown behind a disclosure.
 */
{ type: "user"; text: string; context: string | null } | { type: "agent"; text: string } | { type: "thought"; text: string } | { type: "tool"; call: ToolCall } | { type: "plan"; entries: PlanEntry[] } | 
// A permission request waiting on (or answered by) the human.
{ type: "permission"; requestId: string; toolCallId: string; title: string; options: PermissionOption[]; answer: PermissionAnswer | null } | 
// oxplow's policy rejected the call without asking the human.
{ type: "policy_denied"; toolCallId: string; label: string; reason: string } | 
// A write the policy would deny ran without asking first.
{ type: "bypass"; toolCallId: string; label: string; reason: string } | 
// Something failed: the prompt, the agent process, the protocol.
{ type: "error"; message: string };

export type KeyedDiff = {
	key: string[],
	added: number,
	removed: number,
	changed: number,
	// Up to [`ROW_DIFF_SAMPLES`] of them, in key order.
	samples: RowSample[],
};

/**
 *  Launcher (Cmd+K) sections a lens can be listed under. Mirrors the
 *  renderer's `PageCategory`.
 */
export type LauncherCategory = "Work" | "Code" | "Git" | "Activity" | "Knowledge" | "Data" | "Lenses" | "System";

// A loaded lens.
export type Lens = Lens_Serialize | Lens_Deserialize;

/**
 *  A button on a lens: a command it runs (P6.B1, target §11.4). The
 *  command goes through the bus as `Actor::Lens` acting for whoever
 *  pressed it, so every policy — invokers, the agent policy, confirmation
 *  — applies as if they had run it themselves; a lens can offer a button
 *  but never grant a power. Copying the result and handing it to the
 *  agent are on every lens, not declared.
 */
export type LensAction = {
	// Unique within the lens; `run_lens_action` names it.
	id: string,
	label: string,
	// The command it runs (`oxplow.work_item.transition`).
	command: string,
	/**
	 *  The command's input. A string that is exactly `{{param.<name>}}`
	 *  or `{{row.<column>}}` becomes that value (a number stays a number);
	 *  one that contains them has them spliced in as text.
	 */
	input: unknown,
	/**
	 *  A row action: offered on each row (right-click), with `{{row.*}}`
	 *  bound to that row. Otherwise it's a button above the result.
	 */
	row: boolean,
	/**
	 *  A group action: a button in the heading of the group whose `by`
	 *  value (as text) this is, instead of above the result.
	 */
	group: string | null,
};

/**
 *  When a lens needs attention: its row count reaches `min_rows`, or the
 *  first row's `column` goes `above` / `below` a threshold. A left-nav
 *  panel's `badge` lens shows its count, and the Alerts panel lists it.
 */
export type LensAlert = {
	minRows: number | null,
	column: string | null,
	above: number | null,
	below: number | null,
	// Badge text; else the row count or the column's name.
	label: string | null,
};

// Which result columns a chart viz draws from.
export type LensChart = {
	x?: string | null,
	y?: string | null,
	series?: string | null,
	label?: string | null,
	size?: string | null,
	group?: string | null,
};

// How one result column is shown.
export type LensColumn = {
	// Result column name.
	key: string,
	// Header text; defaults to `key`.
	label?: string | null,
	link?: LensLink | null,
	/**
	 *  A column of the same row holding this one's unit (`ms`, `%`,
	 *  `lines`): a number shows as a metric value in it.
	 */
	unit?: string | null,
	/**
	 *  A column of the same row naming an icon drawn before the cell
	 *  (`done`, `in_progress`, `epic`, `wiki`, …; the UI's fixed
	 *  vocabulary, `lens/lensIcons.tsx` — an unknown name draws none).
	 */
	icon?: string | null,
	/**
	 *  A column of the same row naming the cell's tone: `accent`,
	 *  `success`, `warning`, `danger` or `muted` (anything else is plain).
	 */
	tone?: string | null,
};

// A `custom` lens's component and the props it starts with.
export type LensCustom = LensCustom_Serialize | LensCustom_Deserialize;

// A `custom` lens's component and the props it starts with.
export type LensCustom_Deserialize = {
	// One of the extension's `custom_components` ids.
	component: string | null,
	// Handed to the component as is.
	props?: unknown | null,
};

// A `custom` lens's component and the props it starts with.
export type LensCustom_Serialize = {
	// One of the extension's `custom_components` ids.
	component: string | null,
	// Handed to the component as is.
	props: unknown | null,
};

// `form` viz: the command it submits and the values it starts from.
export type LensForm = LensForm_Serialize | LensForm_Deserialize;

// `form` viz: the command it submits and the values it starts from.
export type LensForm_Deserialize = {
	command: string | null,
	// Input values the form starts with (`{{param.x}}` placeholders bound).
	defaults?: unknown | null,
};

// `form` viz: the command it submits and the values it starts from.
export type LensForm_Serialize = {
	command: string | null,
	// Input values the form starts with (`{{param.x}}` placeholders bound).
	defaults: unknown | null,
};

/**
 *  `group` on a `list` or `table`: the rows under a heading per distinct
 *  value of `by`, in the order each first appears; `link` makes the
 *  heading a link, read from the group's first row.
 */
export type LensGroup = {
	// The column whose value groups the rows (not shown as a cell).
	by: string,
	// The heading's link; `from` defaults to `by`.
	link?: LensLink | null,
};

// `hunks` viz: the file and the two revisions each row diffs.
export type LensHunks = {
	path: string | null,
	from: string | null,
	to: string | null,
};

// A lens, by its rendered text before and after.
export type LensImpact = {
	id: string,
	change: Change,
	before: string | null,
	after: string | null,
	// Why a side couldn't render (its query failed).
	error: string | null,
};

// A lens that didn't run for want of a capability.
export type LensInactive = {
	// The needs that aren't met (`work_items`, `snapshots.contents`).
	needs: string[],
	// What a person reads.
	message: string,
};

// Makes a column's cells link to a page.
export type LensLink = {
	kind: LensLinkKind,
	// Result column holding the target id. Defaults to the column itself.
	from?: string | null,
	// For `file` / `diff-at`: result column holding a line number to open at.
	line?: string | null,
	// For `diff-at`: column holding the older side's label.
	base?: string | null,
	// For `diff-at` / `compare`: column holding the newer side's label.
	head?: string | null,
};

// A page a column value can link to.
export type LensLinkKind = 
// `file:<path>`; the value is a repo-relative path.
"file" | 
// `wiki:<slug>`.
"wiki" | 
// The effort's diff view; the value is an effort id.
"effort-diff" | 
// A git commit; the value is a sha.
"commit" | 
// A metric's page; the value is a metric key.
"metric" | 
/**
 *  Any oxplow page by its tab id (`work_item:oxplow:<id>`,
 *  `commit:<sha>`, `page:git-dashboard`, …),
 *  e.g. `v_page_visit.page_id`.
 */
"page" | 
/**
 *  A file's diff within a change: the value is the path; `line`,
 *  `base` and `head` name the columns holding the line and the
 *  change's `base_revision` / `head_revision` (join `v_change`).
 */
"diff-at" | 
/**
 *  Two line ranges side by side: the value is
 *  `path:start-end|peer:start-end`; `head` names a column with the
 *  revision to read (`working`, `snap:<id>`, `git:<rev>`; the working
 *  tree if absent).
 */
"compare";

/**
 *  A value the viewer (or an agent) can set when running the lens,
 *  bound into the query as `:name`.
 */
export type LensParam = {
	name: string,
	label?: string | null,
	// Used when the caller doesn't supply the param.
	default?: SqlCell | null,
	/**
	 *  The values it takes, when it's a choice: a panel shows
	 *  them as a toggle in its header, a lens page as a select. Its
	 *  `default` must be one; a run supplying another is refused.
	 */
	options?: LensParamOption[],
};

// One value a choice param takes, and what the viewer sees for it.
export type LensParamOption = {
	value: string,
	label: string,
};

// The result of running a lens.
export type LensRun = LensRun_Serialize | LensRun_Deserialize;

// The result of running a lens.
export type LensRun_Deserialize = {
	lens: Lens_Deserialize,
	// The parameter values actually used (supplied or default).
	params: { [key in string]: SqlCell },
	result: SqlQueryResult,
	// The lens's alert on this result, if it declares one.
	alert: AlertState | null,
	/**
	 *  What's worth knowing about its data: a view it read comes from a
	 *  collector failures disabled (P7.C2), so it isn't being refreshed.
	 */
	warnings: string[],
	/**
	 *  Set when the lens needs a capability that isn't active: it didn't
	 *  run, and says what it needs instead of showing nothing.
	 */
	inactive: LensInactive | null,
};

// The result of running a lens.
export type LensRun_Serialize = {
	lens: Lens_Serialize,
	// The parameter values actually used (supplied or default).
	params: { [key in string]: SqlCell },
	result: SqlQueryResult,
	// The lens's alert on this result, if it declares one.
	alert: AlertState | null,
	/**
	 *  What's worth knowing about its data: a view it read comes from a
	 *  collector failures disabled (P7.C2), so it isn't being refreshed.
	 */
	warnings: string[],
	/**
	 *  Set when the lens needs a capability that isn't active: it didn't
	 *  run, and says what it needs instead of showing nothing.
	 */
	inactive: LensInactive | null,
};

// A lens an extension mounts into a core page.
export type LensSlot = {
	/**
	 *  Which page region, from [`SLOTS`] (`effort.review.details`,
	 *  `vcs.commit.details`, …); the lens takes the params it offers.
	 */
	slot: string,
	lensId: string,
};

/**
 *  What a lens shows — the view part of a lens file, and the one shape a
 *  lens is made from: a lens file's body, an agent's answer
 *  (`thread_answer.spec`, P6.C1), what Explore Data saves, and what
 *  [`save_lens`] writes. The rest of a lens file (launcher placement,
 *  actions, an alert) is added by editing it.
 */
export type LensSpec = LensSpec_Serialize | LensSpec_Deserialize;

/**
 *  What a lens shows — the view part of a lens file, and the one shape a
 *  lens is made from: a lens file's body, an agent's answer
 *  (`thread_answer.spec`, P6.C1), what Explore Data saves, and what
 *  [`save_lens`] writes. The rest of a lens file (launcher placement,
 *  actions, an alert) is added by editing it.
 */
export type LensSpec_Deserialize = {
	title: string,
	description?: string,
	/**
	 *  SQL over the `v_*` models, with `:param` bindings. Only a `form`
	 *  may leave it empty.
	 */
	query?: string,
	viz?: LensViz,
	params?: LensParam[],
	columns?: LensColumn[],
	empty?: string | null,
	chart?: LensChart | null,
	tree?: LensTree | null,
	timeline?: LensTimeline | null,
	steps?: LensSteps | null,
	hunks?: LensHunks | null,
	form?: LensForm_Deserialize | null,
	group?: LensGroup | null,
	emphasis?: string | null,
	depth?: string | null,
};

/**
 *  What a lens shows — the view part of a lens file, and the one shape a
 *  lens is made from: a lens file's body, an agent's answer
 *  (`thread_answer.spec`, P6.C1), what Explore Data saves, and what
 *  [`save_lens`] writes. The rest of a lens file (launcher placement,
 *  actions, an alert) is added by editing it.
 */
export type LensSpec_Serialize = {
	title: string,
	description: string,
	/**
	 *  SQL over the `v_*` models, with `:param` bindings. Only a `form`
	 *  may leave it empty.
	 */
	query: string,
	viz: LensViz,
	params: LensParam[],
	columns: LensColumn[],
	empty: string | null,
	chart: LensChart | null,
	tree: LensTree | null,
	timeline: LensTimeline | null,
	steps: LensSteps | null,
	hunks: LensHunks | null,
	form: LensForm_Serialize | null,
	group: LensGroup | null,
	emphasis: string | null,
	depth: string | null,
};

// `steps` viz: each step's text and status.
export type LensSteps = {
	label: string | null,
	status: string | null,
};

// `timeline` viz: when each row happened and what it says.
export type LensTimeline = {
	at: string | null,
	label: string | null,
	// A column holding a canonical ref each entry links to.
	ref: string | null,
};

// `tree` viz: which columns nest the rows.
export type LensTree = {
	id: string | null,
	parent: string | null,
	label: string | null,
};

// How a lens renders its rows.
export type LensViz = 
// Rows and columns.
"table" | 
/**
 *  One line per row: the first column (or the first `columns` entry)
 *  is the headline, the rest are secondary.
 */
"list" | 
// A single value: the first column of the first row.
"number" | 
// The first column of the first row, rendered as markdown.
"markdown" | 
// Bars: `chart.x` labels, `chart.y` values.
"bar" | 
/**
 *  A line over `chart.x` (a time or number), `chart.y` values, one
 *  line per `chart.series` value when set.
 */
"line" | 
/**
 *  Nested rectangles sized by `chart.size`, labelled by `chart.label`,
 *  grouped (and coloured) by `chart.group`.
 */
"treemap" | 
/**
 *  Other lenses (`children`), stacked, each given the params it
 *  declares from this lens's params.
 */
"grid" | 
/**
 *  Rows nested by `tree.parent` (a row's parent is the row whose
 *  `tree.id` it names; none, or one not in the result, is a root),
 *  each shown as `tree.label`.
 */
"tree" | 
/**
 *  Rows in time order (`timeline.at`), each shown as
 *  `timeline.label`, linked through `timeline.ref` when set.
 */
"timeline" | 
// The first row as label/value pairs (the displayed columns).
"detail" | 
/**
 *  An ordered checklist: `steps.label`, with `steps.status` (`done`,
 *  `active`, `failed`, anything else pending).
 */
"steps" | 
/**
 *  Per row, the diff of the file `hunks.path` between the revisions
 *  `hunks.from` and `hunks.to` (`working`, `snap:<id>`,
 *  `<vcs>:<rev>`), read-only.
 */
"hunks" | 
/**
 *  A form for command `form.command`: its fields from the command's
 *  input schema, prefilled from `form.defaults` (placeholders bound
 *  like an action's) and the query's first row, if the lens has one.
 *  Submitting runs the command as the lens.
 */
"form" | 
/**
 *  The extension's own web component (`custom.component`), in
 *  a sandboxed frame; its rows are what it shows and what an agent
 *  reads (as a table).
 */
"custom";

// A loaded lens.
export type Lens_Deserialize = {
	/**
	 *  `<extension>/<slug>`: the stable id used by `lens:` page refs,
	 *  `run_lens` and `get_lens`.
	 */
	id: string,
	extension: string,
	slug: string,
	title: string,
	description: string,
	query: string,
	viz: LensViz,
	params: LensParam[],
	columns: LensColumn[],
	empty: string | null,
	// Columns a chart viz draws from.
	chart: LensChart | null,
	tree: LensTree | null,
	timeline: LensTimeline | null,
	steps: LensSteps | null,
	hunks: LensHunks | null,
	form: LensForm_Deserialize | null,
	// For `custom`: the component and its props.
	custom: LensCustom_Deserialize | null,
	// For `list` / `table`: rows under a heading per value.
	group: LensGroup | null,
	/**
	 *  For `list` / `table` / `tree`: a column whose truthy value
	 *  highlights the row.
	 */
	emphasis: string | null,
	// For `list` / `table`: a column whose integer value indents the row.
	depth: string | null,
	// For `grid`: child lens ids.
	children: string[],
	// Launcher section; `None` = "Lenses".
	launcherCategory: LauncherCategory | null,
	// Not listed in the launcher.
	hidden: boolean,
	// Commands the lens offers, as buttons or row actions (P6.B1).
	actions: LensAction[],
	// When the lens needs attention (its panel's badge).
	alert: LensAlert | null,
	/**
	 *  The capabilities (or their features) it needs (`needs:
	 *  [work_items]`): without them its run says so instead of running.
	 */
	needs: string[],
	// Repo-relative path of the lens file.
	path: string,
};

