export type Lifecycle = "stable" | "experimental";

export type LspServerConfig = {
	languageId: string,
	extensions: string[],
	command: string,
	args?: string[],
};

/**
 *  One row of `list_servers()` — everything the settings page and the
 *  agent need to reason about a configured server.
 */
export type LspServerListing = {
	languageId: string,
	extensions: string[],
	command: string,
	args: string[],
	source: LspServerSource,
	// Mason package name when `source == Installed`.
	packageName: string | null,
	// Installed package version when `source == Installed`.
	version: string | null,
	binaryExists: boolean,
	// Stream ids with a live session for this language.
	runningStreams: string[],
	/**
	 *  `completionProvider.triggerCharacters` from a running session's
	 *  server capabilities, when one exists.
	 */
	completionTriggerCharacters: string[] | null,
};

// Where a server config came from, for the settings UI.
export type LspServerSource = "yaml" | "installed";

/**
 *  A model's freshness policy beyond the default (computed on read):
 *  `on_change`, or `{ every: 1h }`.
 */
export type Materialize = 
// A named policy: `on_change`.
MaterializePolicy | 
/**
 *  Stored and recomputed, whole, on a clock — `{ every: 1h }` (the
 *  collectors' grammar: minutes `15m` or hours `2h`) — whatever its
 *  inputs do: for SQL that reads the time (`'now'`), whose answer
 *  moves without a write.
 */
({ every: string }) & { incremental?: never } | 
/**
 *  Stored, and kept by appending the rows past its watermark —
 *  `{ incremental: <column> }`, a declared INTEGER that only grows —
 *  refilled whole when an input saw a rewrite.
 */
({ incremental: string }) & { every?: never };

// The named materialization policies.
export type MaterializePolicy = 
// Stored in its table and recomputed, whole, when an input changes.
"on_change";

// How the adapter reaches the MCP server: exactly one of the two.
export type McpServer = 
// A program in the folder, spoken to over its stdio.
({ command: string[] }) & { auth?: never; url?: never } | 
/**
 *  A server reached over streamable HTTP. `auth` names the
 *  credential whose value is sent as its bearer token.
 */
({ url: string; auth: string | null }) & { command?: never };

/**
 *  One entry in the top-level `measures:` block — the **measure catalog**
 *  authoring surface. A measure is a *type of atomic
 *  fact* a collector may emit (`oxplow.complexity`, `acme.api_latency`, …); the
 *  `oxplow.*` built-ins are seeded by the DB migration, so config only *adds*
 *  global/project measures. Unlike [`MetricEntry`] there is no `use:`/`key:`
 *  split — a measure entry is always a definition (you declare the fact type,
 *  you don't "enable" one). Resolved across the global+project scopes by
 *  [`resolve_measures`] and seeded into the `measure` table at boot.
 */
export type MeasureEntry = {
	// The new measure's namespaced key (`<vendor>.<id>`). Required.
	key?: string | null,
	title?: string | null,
	unit?: string | null,
	// The grain's subject kind (`symbol` | `file` | `test` | `model` | …).
	subjectKind?: string | null,
	/**
	 *  `additive` | `semi-additive` | `non-additive` — additivity OVER TIME
	 *  (default `semi-additive`).
	 */
	temporalSemantics?: string | null,
	/**
	 *  `complete` | `per-path` — what ONE capture restates (default `complete`).
	 *  A SEPARATE AXIS from `temporalSemantics`: `complete` means every capture
	 *  restates the whole population (a coverage report, a test run), so the
	 *  temporal fold applies directly. `per-path` means a capture restates only the
	 *  paths in its snapshot — which is what a **tree collector over a per-commit delta**
	 *  does. Such a measure is folded to the latest capture per (producer, path)
	 *  before aggregating, so a repo-wide total stays correct while only changed
	 *  files are rescanned. Set this on any measure a snapshot-triggered collector
	 *  emits per-file facts on.
	 */
	captureScope?: string | null,
	description?: string | null,
};

export type MenuGroupSnapshot = {
	id: string,
	label: string,
	items: MenuItemSnapshot[],
};

export type MenuItemSnapshot = {
	id: string,
	label: string,
	shortcut: string | null,
	enabled: boolean,
	checked: boolean | null,
	/**
	 *  When present, this item is a nested submenu of these children
	 *  (e.g. File ▸ Open Recent ▸ …) rather than a leaf command.
	 */
	submenu?: MenuItemSnapshot[] | null,
};

/**
 *  A command's place in the menu bar: which menu, the group it sits in
 *  (VS Code's: groups are sorted by name and drawn apart by a separator)
 *  and where in the group (lowest first).
 */
export type MenuPlace = {
	// `file` or `edit`.
	bar: string,
	// Its group (`1_project`, `2_save`); absent, the menu's first.
	group?: string | null,
	order: number,
};

// Whether `head` would merge into `base` cleanly.
export type MergeReadiness = 
// `head` has nothing `base` lacks.
"already_integrated" | 
// `head` is ahead and no file changed on both sides.
"clean" | 
// `head` is ahead and some file changed on both sides.
"conflict";

/**
 *  One entry in the top-level `metrics:` block — a **pure read-time SPEC** over a
 *  measure. A metric no longer *computes* anything: it names a
 *  `sourceMeasure` + an `aggregation` (+ optional `filter`), or a `formula` over
 *  other metrics, and the engine aggregates the durable facts a `collectors:` entry
 *  emitted. Two forms, distinguished by which key is set:
 *  - **`use:`** — enable an existing catalog metric by key (built-in/global),
 *    optionally overriding `target`/thresholds for this project.
 *  - **`key:`** — define a NEW spec (`sourceMeasure` + `aggregation`, or `formula`).
 * 
 *  Resolved across the three scopes into [`ResolvedSpec`]s. All non-discriminant
 *  fields are optional so both forms share one struct; validation enforces the
 *  per-form rules.
 */
export type MetricEntry = {
	// `use:` form — the catalog key to enable.
	use?: string | null,
	// `key:` form — the new metric's namespaced key.
	key?: string | null,
	/**
	 *  Active flag. `None`/`Some(true)` = active (a bare `use:`/`key:` entry is
	 *  on); `Some(false)` = an explicit **disable marker** kept in config so a
	 *  default-ON metric (producer/extension) or a config-defined metric can be
	 *  turned off without deleting its definition. Not a structural field, so a
	 *  `use:` entry may carry it (unlike measure/aggregation/filter/formula).
	 */
	enabled?: boolean | null,
	title?: string | null,
	/**
	 *  The measure whose facts this metric aggregates (required for a `key:`
	 *  metric unless it sets `formula`). NULL for a pure formula metric.
	 */
	sourceMeasure?: string | null,
	/**
	 *  `count` | `sum` | `avg` | `min` | `max` | `last` | `ratio` (default `last`).
	 *  Combines the facts WITHIN a capture; cross-time collapse is governed by the
	 *  source measure's `temporalSemantics`.
	 */
	aggregation?: string | null,
	// Fact predicate applied before aggregation (`minValue` / `severity` / `dimEq`).
	filter?: FilterConfig | null,
	/**
	 *  Derived-metric formula over other metric keys (mutually exclusive with
	 *  `sourceMeasure`).
	 */
	formula?: FormulaConfig | null,
	unit?: string | null,
	// `higher-better` | `lower-better` | `neutral` (default `neutral`).
	direction?: string | null,
	/**
	 *  Read-time presentation: `gauge` | `findings` | `test` | `coverage` |
	 *  `event` (default `gauge`).
	 */
	displayKind?: string | null,
	// Catalog grouping: `operational` | `testing` | `coverage` | `static-quality` | `custom`.
	category?: string | null,
	// Language this metric measures (e.g. `rust`), for the catalog filter.
	language?: string | null,
	/**
	 *  One-line human description (shown atop the Metric Detail page). Inherent to
	 *  the definition — a `use:` can't override.
	 */
	description?: string | null,
	// Conformed-dimension keys this metric can be sliced by (drill-across).
	sliceableDims?: string[],
	target?: number | null,
	warnAt?: number | null,
	failAt?: number | null,
	/**
	 *  Entity metric: the `v_*` view it aggregates, instead of a
	 *  measure's facts. Fragments below are SQL over that view, aliased `e`.
	 */
	entity?: string | null,
	// Entity metric: which rows count (a SQL condition).
	where?: string | null,
	/**
	 *  Entity metric: the timestamp column/expression that makes it an EVENT
	 *  metric (rows bucketed by when they happened). Without it the metric is
	 *  a STATE metric: its current value, captured over time.
	 */
	time?: string | null,
	// Entity metric: the value expression aggregated (not needed for `count`).
	value?: string | null,
};

// One model as its owner declares it (an entry of `models.yaml`).
export type ModelDecl = {
	name: string,
	version: number,
	description: string,
	// The contract: the view's columns, in order.
	columns: ColumnDecl[],
	/**
	 *  The columns whose values name one row: declared columns,
	 *  part of the contract. A key implies its test (never null, never
	 *  repeated), and a materialized model's table takes it as its
	 *  primary key.
	 */
	key?: string[],
	tests?: TestDecl[],
	/**
	 *  Earlier versions kept published beside this one after a breaking
	 *  change, each as `<view>_v<version>` until its date.
	 */
	deprecated?: Deprecated[],
	/**
	 *  How it is computed: absent, on read (a view); `on_change`, stored
	 *  and recomputed when one of its inputs changes; `{ every: 1h }`,
	 *  stored and recomputed on that clock.
	 */
	materialize?: Materialize | null,
};

// When one model last changed.
export type ModelFreshness = {
	model: string,
	// RFC 3339.
	changedAt: string,
};

export type ModelImpact = {
	view: string,
	change: Change,
	/**
	 *  For a changed model, the parts that differ, in order: `query`,
	 *  `columns`, `description`, `tests`, `version`, `deprecated`.
	 */
	changed: string[],
	beforeColumns: string[],
	afterColumns: string[],
	// The first difference in its contract (columns, types, docs).
	contractChange: string | null,
	// Models that read it, which a contract change can break.
	downstream: string[],
	/**
	 *  What its rows would become, each side read through its own
	 *  models; `None` for an unchanged model.
	 */
	rows: RowDiff | null,
};

// A model's declaration and its SQL file.
export type ModelSource = {
	decl: ModelDecl,
	// Where the SQL came from, for error locations (`models/work_item.sql`).
	file: string,
	sql: string,
	/**
	 *  For a kept earlier version (named `<name>_v<version>`): what it's a
	 *  version of. Its columns are filled from the contract that version
	 *  published when it compiles.
	 */
	twin: Twin | null,
};

export type NoteId = string;

/**
 *  How a credential is obtained by signing in: OAuth 2.1's
 *  authorization-code flow with PKCE, run by oxplow — the provider only
 *  ever sees the access token.
 */
export type OAuthDecl = {
	// Where the person signs in.
	authorize_url: string,
	// Where a code, or a refresh token, is exchanged for an access token.
	token_url: string,
	client_id: string,
	scopes?: string[],
	/**
	 *  The **name** of another (static) credential of this provider that
	 *  holds the client secret, for a service that requires one.
	 */
	client_secret?: string | null,
	/**
	 *  The loopback port the redirect comes back on, for a service that
	 *  wants one registered; any free port otherwise.
	 */
	redirect_port?: number | null,
	/**
	 *  How the client secret is sent with a token request: `basic` (an
	 *  `Authorization` header, RFC 6749 §2.3.1 — what every service must
	 *  take; the default) or `post` (in the form, for a service that wants
	 *  that).
	 */
	client_auth?: ClientAuth,
};

/**
 *  A redirect listener: its id — what waits on it, answers it and stops
 *  it (tsk905), never its port — and the port to sign in on.
 */
export type OAuthListener = {
	id: number,
	port: number,
};

/**
 *  What a mutation did. `log` is the provider's own account (a CLI's
 *  output) for the person to read.
 */
export type OpOutcome = {
	success: boolean,
	log: string,
	// Paths still conflicted after the operation.
	conflicts: string[],
	// Conflicts oxplow's smart merge resolved on its own.
	auto_resolved: number,
};

// An operation of a scope (`scope: tabs.write`, `op: open`).
export type OpRef = {
	scope: string,
	op: string,
};

export type OxplowConfig = {
	/**
	 *  The agent harnesses enabled for this project, by registry key, in
	 *  priority order: the first is a new session's default. Empty (the
	 *  default) enables every registered harness, the first declared one
	 *  the default.
	 */
	agents: string[],
	/**
	 *  Human-readable project name. Defaults to the basename of the
	 *  project dir when not set in .oxplow/project.yaml.
	 */
	projectName: string,
	// Extra language servers registered on top of the built-ins.
	lspServers: LspServerConfig[],
	// User-supplied text appended verbatim to every agent's system prompt.
	agentPromptAppend: string,
	// File-snapshot retention window in days. 0 disables pruning.
	snapshotRetentionDays: number,
	/**
	 *  Metric-capture retention window in days: captures older than the
	 *  cutoff are pruned (facts cascade) — EXCEPT effort-stamped ones
	 *  (attribution history), each producer's newest capture, and any capture
	 *  still contributing a current value to the fold. **0 (the default)
	 *  keeps everything** (tsk93); pruning trades away per-test drill-down /
	 *  flakiness horizon for bounded growth, so it is strictly opt-in.
	 */
	metricRetentionDays: number,
	/**
	 *  Keep the per-run `detail_json` drill-in payload for only the newest N
	 *  captures **per producer**; older ones are compacted (the payload is
	 *  nulled, the capture and all its facts stay). `0` disables the cap.
	 * 
	 *  This is the knob that bounds a BUSY project: the payload is ~0.5 MB per
	 *  coverage run, so age alone never catches up with a repo that runs tests
	 *  dozens of times a day (tsk211). Compaction never changes a metric value
	 *  — only the effort Tests/Coverage panel's detail for old runs is lost.
	 */
	metricDetailMaxPerProducer: number,
	/**
	 *  Compact `detail_json` older than this many days. `0` disables it.
	 *  Complements [`Self::metric_detail_max_per_producer`]: the count cap
	 *  bounds a busy repo, this reaches a project that has gone quiet.
	 */
	metricDetailRetentionDays: number,
	/**
	 *  Extra `exclude`/`include` paths layered on top of `.gitignore`
	 *  for fs-watch / snapshot capture / code-quality scans. `.git`,
	 *  `.oxplow`, and everything in `.gitignore` (+ `.git/info/exclude`)
	 *  are ignored automatically — this only adds extras or forces
	 *  gitignored paths back in. See [`GeneratedConfig`].
	 */
	generated: GeneratedConfig,
	/**
	 *  Maximum blob size for content-addressed snapshotting; larger
	 *  files get a stat-only entry. Default 5 MiB.
	 */
	snapshotMaxFileBytes: number,
	/**
	 *  How long the Stop hook waits for the turn-end snapshot, in ms.
	 *  A take that runs longer keeps going in the background and is
	 *  recorded as over budget. Default 2000.
	 */
	snapshotTurnBudgetMs: number,
	/**
	 *  How many of a snapshot's changed files the symbol collector asks
	 *  the running language servers about; the rest are recorded as
	 *  skipped. Default 50.
	 */
	symbolsMaxFilesPerSnapshot: number,
	/**
	 *  When true, the UserPromptSubmit hook injects a session-context
	 *  block into every agent prompt.
	 */
	injectSessionContext: boolean,
	/**
	 *  Hex colour composited behind this project's app icon, so concurrent
	 *  windows are tellable apart at a glance (`#c2410c`, `#abc`, or
	 *  unprefixed). `None` leaves the stock icon alone.
	 * 
	 *  Per-project rather than a dev-only flag: colour-coding *any* checkout is
	 *  the general case, and "this is the dev build" is just one instance of
	 *  it. Consumed on macOS only — see the desktop shell's `icon_tint`.
	 * 
	 *  No `skip_serializing_if`: this type is a command result, and specta
	 *  rejects conditional omission in unified mode. Absence from the written
	 *  YAML is handled by `render_project_config`, which builds its mapping by
	 *  hand rather than through this derive.
	 */
	iconTint: string | null,
	// How the project's tests run (the `testing:` block).
	testing: TestingConfig,
	/**
	 *  Project-declared metric SPECS (the `metrics:` block) — the author-able
	 *  read surface (epic tsk12, E). Each entry enables a catalog metric
	 *  (`use:`) or defines a new spec (`key:`) over a measure. The runner resolves
	 *  these across the built-in/global/project scopes; see [`resolve_metrics`].
	 */
	metrics?: MetricEntry[],
	/**
	 *  The project's collectors (the `collectors:` block, P7.B3): fact
	 *  producers that run on their trigger and record facts on the measures
	 *  they declare. Owner [`collectors::PROJECT`].
	 */
	collectors?: CollectorSpec[],
	/**
	 *  Project-declared measures (the `measures:` block) — custom fact TYPES a
	 *  collector may emit (epic tsk12, workstream E). The `oxplow.*` built-ins
	 *  are seeded by the DB migration; these add global/project ones. Resolved
	 *  by [`resolve_measures`] and seeded into the `measure` catalog at boot.
	 */
	measures?: MeasureEntry[],
	/**
	 *  Project-declared dimensions (the `dimensions:` block) — custom conformed
	 *  slice axes (epic tsk12, workstream E). Resolved by [`resolve_dimensions`]
	 *  and seeded into the `dimension` catalog at boot.
	 */
	dimensions?: DimensionEntry[],
	/**
	 *  Project-declared architectural zones (the `zones:` block) — an
	 *  ORDERED table, first match wins. Empty (the default) means oxplow
	 *  classifies nothing: every file is `other` and the Change-analysis
	 *  zone surfaces stay empty until the project declares its own.
	 */
	zones?: ZoneRuleConfig[],
	/**
	 *  Each harness's configuration, by its key: what its `launch` reads,
	 *  e.g. `agentConfig: { opencode: { model: "github-copilot/gpt-5-mini" } }`.
	 */
	agentConfig: { [key in string]: unknown },
	/**
	 *  The project's ACP agents (`acpAgents:`), layered over the declared
	 *  ACP adapters (`oxplow_app::acp::agents::resolve`).
	 */
	acpAgents: AcpAgentConfig[],
	/**
	 *  The project's extension provider instances
	 *  (`extensionInstances: { "<ext>/<id>": { enabled, config } }`).
	 */
	extensionInstances: { [key in string]: ExtensionInstanceConfig },
	/**
	 *  The project's choice of implementation per choosable capability
	 *  (`activeProviders: { work_items: issues, effort_policy: none }`); a
	 *  capability absent here keeps its default.
	 */
	activeProviders: { [key in string]: string },
	/**
	 *  A person's own choices (`activeProviders` in
	 *  `.oxplow/personal.yaml`), over the project's.
	 */
	personalActiveProviders: { [key in string]: string },
	/**
	 *  What a new thread starts with, a person's own (`newThreadSession`
	 *  in `.oxplow/personal.yaml`): `ask` (the session picker), `none`, or
	 *  an agent (`<harness>` / `<harness>:<acp agent>`). Unset means `ask`.
	 */
	personalNewThreadSession: string | null,
	/**
	 *  Core components no extension's replacement may take over
	 *  (`replacementsOff: [work_item.board]`): oxplow's own shows there
	 *  even when the active provider's extension replaces it.
	 */
	replacementsOff: string[],
	/**
	 *  How long this project keeps each event namespace's payloads and
	 *  large content (`eventRetention: { agent: { payloadDays,
	 *  contentDays } }`), over core's defaults; an extension's namespace is
	 *  kept no longer than its own window.
	 */
	eventRetention: { [key in string]: RetentionWindow },
	/**
	 *  This project's AI role assignments (`ai: { roles: … }`), layered
	 *  over the user-global `ai.yaml`. Keyed by role name (one of
	 *  [`AI_ROLE_NAMES`]). Provider ids refer to each person's `ai.yaml`.
	 */
	aiRoles: { [key in string]: AiRoleOverride },
	/**
	 *  Extensions turned off for this project (`extensions: { disabled:
	 *  [...] }`), bundled ones included. Committed, so it's team-wide.
	 */
	extensionsDisabled: string[],
};

/**
 *  What changed. Variants are deliberately broad — the renderer
 *  refetches the affected bucket on receipt rather than trying to
 *  reconcile diffs from the payload.
 */
export type OxplowEvent = 
// Followups for a thread.
{ kind: "followupsChanged"; threadId: ThreadId } | 
// Background task progress.
{ kind: "backgroundTasksChanged" } | 
/**
 *  The set of known language servers changed (Mason package
 *  installed or removed). Renderer refetches `list_lsp_servers`.
 */
{ kind: "lspServersChanged" } | 
/**
 *  Per-thread per-pane agent status changed. `state` carries the
 *  derived status so the renderer can update without a refetch
 *  round-trip — sources that don't have it pre-derived (e.g.
 *  PreToolUse/PostToolUse, where the renderer used to refetch and
 *  re-derive) compute it inline before emitting.
 */
{ kind: "agentStatusChanged"; threadId: ThreadId; 
/**
 *  The thread's stream, so a view over every stream (the Git
 *  dashboard) files it without a lookup.
 */
streamId: StreamId; 
/**
 *  The agent session whose status it is; `None` for activity no
 *  session claims. The renderer rolls a thread's sessions up
 *  (`rollUpAgentStatus`).
 */
agentSessionId: AgentSessionId | null; state: AgentStatusState; 
/**
 *  The status detail, when meaningful to the renderer. Carries
 *  what the agent is waiting on (its question, the permission it
 *  asked) when `state` is `AwaitingUser`, so the rail dot's tooltip
 *  can show it — `None` for every other transition.
 */
detail: string | null } | 
/**
 *  A snapshot take recorded something new: a new snapshot (its
 *  `file_count` rows), or — `trigger: HeadMoved`, 0 files — the
 *  current snapshot re-stamped with a new HEAD. Emitted after the
 *  take's transaction commits (`SqliteSnapshotStore::record_take`),
 *  never for an unchanged take. The durable record is the
 *  `snapshot_op` row and the `snapshot.taken` / `vcs.head.moved`
 *  event in the log; this is the UI / reactor wake-up.
 */
{ kind: "snapshotTaken"; streamId: StreamId; snapshotId: number; fileCount: number; trigger: SnapshotTrigger; threadId: ThreadId | null; turnId: number | null; effortId: EffortId | null } | 
/**
 *  Published models (views) changed: a commit touched a table one of
 *  them reads, directly or through other models (P4.6). A lens re-runs
 *  when a model it read is listed.
 */
{ kind: "modelsChanged"; models: string[] } | 
/**
 *  One or more metric samples landed in `stream_id` (unified metric
 *  substrate, tsk213). `measures` names the measure keys the write touched
 *  so a consumer can skip an event that can't affect it (tsk198); an EMPTY
 *  list is fail-open — "unknown, refresh anyway" — which is what the
 *  low-frequency emit sites still send. See `.context/metrics.md`.
 */
{ kind: "metricSamplesChanged"; streamId: StreamId; measures?: string[] } | 
/**
 *  `.oxplow/project.yaml` was reloaded from disk (external edit, e.g. the agent
 *  running `/oxplow:configure`). The in-memory config has been swapped;
 *  the renderer refetches `get_config`.
 */
{ kind: "configChanged" } | 
/**
 *  The extension catalog may have changed: a file under the primary
 *  worktree's `oxplow/extensions/` did, or the `extensions` config key
 *  (the catalog's own signal, tsk1030). Every host listing what
 *  extensions contribute — the launcher, pages, panels, slots —
 *  reloads, and a lens re-runs its definition.
 */
{ kind: "extensionsChanged" } | 
/**
 *  A command running on the daemon calls a scope the window
 *  hosts (`client_host.rs`): the window does `scope`'s `op` with
 *  `input` — in `thread_id`'s tabs, or the one it shows when `None` —
 *  and answers `answer_client_call { id, … }`.
 */
{ kind: "clientCall"; id: string; 
/**
 *  The window it's for (its `register_client_host` id): only that
 *  one does it and answers.
 */
client: string; threadId: ThreadId | null; 
// Who ran the command (`agent:thr3`, `human`).
actor: string; scope: string; op: string; input: unknown } | 
/**
 *  A person approved a program on this machine (a provider, collector,
 *  effect, component, ACP agent): what shows approval state —
 *  Settings → Integrations and Data — refreshes (tsk1040). Approvals
 *  are per machine, not config, so `ConfigChanged` never said so.
 */
{ kind: "approvalsChanged" } | 
/**
 *  `.git` directory appeared/disappeared at the project root —
 *  "is this a git workspace" flipped. Renderer hides/restores the
 *  git-aware UI on receipt.
 */
{ kind: "workspaceContextChanged"; vcsEnabled: boolean } | 
/**
 *  A worktree file changed on disk. Renderer-wide: file tree, quick
 *  open, project panel, git dashboard, uncommitted changes view all
 *  refresh in response.
 */
{ kind: "workspaceChanged"; streamId: StreamId; changeKind: WorkspaceChangeKind; path: string } | 
/**
 *  A ref under `.git/refs/` changed. Drives history, branch list,
 *  and ahead/behind refreshes. Coarse per stream.
 */
{ kind: "vcsRefsChanged"; streamId: StreamId } | 
/**
 *  A non-primary stream's backing worktree was deleted out from
 *  under us (externally `rm -rf`'d, `git worktree remove`'d, etc.).
 *  The runtime has already archived the stream by the time this
 *  fires; the renderer surfaces a toast so the user knows why the
 *  rail row vanished. `title` carries the archived stream's display
 *  name.
 */
{ kind: "streamOrphaned"; streamId: StreamId; title: string } | 
/**
 *  A sign-in for provider instance `instance`'s credential `name`
 *  finished (P9.B3): its token is in the keychain and the instance
 *  restarted on it — or, with `error`, it came to nothing and why.
 *  The keychain is no model, so there is nothing to re-read but the
 *  instances themselves (`list_provider_instances`).
 */
{ kind: "credentialChanged"; instance: string; name: string; 
/**
 *  The sign-in this news is about, when it is about one (tsk929):
 *  a row waiting on another sign-in of the same credential
 *  ignores it.
 */
signIn: number | null; error: string | null };

/**
 *  When an `on:` collector runs after a triggering event. Empty,
 *  at once — as before pacing existed. Otherwise the run is deferred
 *  (recorded `pending`, so views can say "updating…") until every set
 *  condition holds, then runs once for the latest triggering event:
 *  - `settle` — no triggering event has arrived for that long;
 *  - `at_most` — that long has passed since its last run (a deferred run
 *    always follows, so the result is never left stale);
 *  - `idle` — no agent turn is running and nothing changed (no snapshot or
 *    agent event) for that long.
 * 
 *  An event type in `force` runs at once, past them all: a moment that
 *  needs the result fresh (an effort finishing, a commit).
 */
export type Pacing = {
	settleSecs: number | null,
	atMostSecs: number | null,
	idleSecs: number | null,
	force: string[],
};

export type PageVisit = {
	id: string,
	page_kind: string,
	page_id: string,
	/**
	 *  Human-readable label captured at activation time — the same
	 *  string the tab strip displays. NULL when none was captured (the
	 *  renderer falls back to page_id).
	 */
	label: string | null,
	visited_at: Timestamp,
	duration_ms: number | null,
	thread_id: string | null,
};

// One panel's place in the layout.
export type PanelPlacement = {
	panel: string,
	hidden: boolean,
	collapsed: boolean,
};

/**
 *  What a left-nav panel is bound to: the project, the current stream, or
 *  the current thread — which of `stream_id` / `thread_id` its lenses get.
 */
export type PanelScope = "project" | "stream" | "thread";

// How a permission request was answered.
export type PermissionAnswer = { type: "selected"; optionId: string } | { type: "cancelled" };

export type PermissionKind = "allow_once" | "allow_always" | "reject_once" | "reject_always";

export type PermissionOption = {
	id: string,
	name: string,
	kind: PermissionKind,
};

export type PlanEntry = {
	content: string,
	status: PlanStatus,
};

export type PlanStatus = "pending" | "in_progress" | "completed";

// What kind of project program it is.
export type ProgramKind = 
/**
 *  A project collector's program (`collectors:` with `runtime: exec`):
 *  one that records facts, or a report parser (`records:`).
 */
"collector" | 
// An agent spoken to over ACP (`acpAgents`, tsk335).
"acp-agent" | 
/**
 *  A shared extension's advisories: SQL whose results go into the
 *  agent's context (tsk352). Bundled extensions' aren't gated.
 */
"advisories" | 
/**
 *  An extension's provider (`providers:`): a long-lived program
 *  implementing a capability, approved with its declarations.
 */
"provider" | 
/**
 *  An extension's effect (`effects:`, P8.D9): a script that reacts to
 *  events by running commands, approved over its extension's folder.
 */
"effect" | 
/**
 *  A custom component that declares `commands` (P11, tsk960): a bundle
 *  that may run them with the viewer's rights, approved over its
 *  bundle and the commands it names. One that declares none only shows
 *  and queries, and needs no approval.
 */
"component" | 
/**
 *  An AI provider written as a script (`implementations:` with a
 *  `.star` entry): its calls carry the person's key and prompts,
 *  approved over its script and the base URL it sends to — a shipped
 *  one too, so a changed script asks again.
 */
"ai-provider" | 
/**
 *  An effort policy written as a script (`implementations:` with a
 *  `.star` entry): it composes commands for core's events, as an
 *  effect does, approved over its extension's folder (the manifest's
 *  `needs` says what it reads).
 */
"effort-policy";

// A program the project's config would run.
export type ProjectProgram = {
	kind: ProgramKind,
	/**
	 *  The capability it implements (a provider): what approving it lets
	 *  it do (an agent harness launches the person's agent sessions).
	 */
	capability: string | null,
	// The collector, agent, extension or component it belongs to.
	name: string,
	// Project-relative path of the program.
	program: string,
	args: string[],
	/**
	 *  Extra environment it runs with, as `NAME=value` (ACP agents), or
	 *  the host variables it gets by name (a provider).
	 */
	env: string[],
	// Keychain credentials it gets, by name (a provider).
	credentials: string[],
	// Hosts it may reach (a provider).
	network: string[],
	// The commands it may run with the viewer's rights (a component).
	commands: string[],
	// The scopes it may call (a provider's `needs`).
	scopes: string[],
	/**
	 *  The project-relative folder whose every file the approval covers
	 *  (a provider's extension, declarations included).
	 */
	tree: string | null,
	/**
	 *  `program` is a url — a server run elsewhere (an MCP server by
	 *  `url`) — not a file: the approval covers the url itself, and what
	 *  the server is isn't in it.
	 */
	remote: boolean,
	// This machine approved it as it is now.
	approved: boolean,
	/**
	 *  Its approval hash as it is now (`None` when it can't be read). The
	 *  person's approve click sends back the version they reviewed.
	 */
	version: string | null,
};

// Who offers a prompt.
export type PromptSource = 
/**
 *  One of core's areas (`vcs`, `work_items`, `knowledge`,
 *  `code_intel`, `extensions`).
 */
{ kind: "area"; name: string } | 
// An extension.
{ kind: "extension"; name: string };

export type ProviderConfig = {
	/**
	 *  Your name for it, e.g. `anthropic` or `local-ollama`. Also the
	 *  keychain entry name for its key.
	 */
	id: string,
	/**
	 *  What it is: a declared `ai_provider` id (`anthropic`, `openai`,
	 *  `openai_compatible`, `openrouter`, `typesafe`).
	 */
	kind: string,
	/**
	 *  Its API base: required for a kind with no default
	 *  (`openai_compatible`), an override for the others.
	 */
	baseUrl?: string | null,
};

export type ProviderImpact = {
	id: string,
	capability: string,
	change: Change,
	before: Grants | null,
	after: Grants | null,
	commands: CommandChange[],
	// Behind the MCP adapter: each pinned tool of its server.
	tools: CommandChange[],
	featuresBefore: unknown | null,
	featuresAfter: unknown | null,
	/**
	 *  For a changed provider, where its spec and declarations first
	 *  differ — what a person reads when no grant, command or feature
	 *  line shows the change.
	 */
	firstDifference: string | null,
	/**
	 *  What approving it would change, as sentences ([`approval_lines`]):
	 *  what Settings → Data shows before a person approves.
	 */
	lines: string[],
};

// An instance as Settings → Integrations shows it.
export type ProviderInstanceView = {
	// `<extension>/<instance id>`.
	instance: string,
	/**
	 *  The project's, or the person's on this machine (every project).
	 *  A project's entry is the project's, config and credentials, even
	 *  where it replaces a global one of the same name (tsk838).
	 */
	scope: Scope,
	/**
	 *  This project's own entry replaces a global instance of the same
	 *  name here.
	 */
	overridden: boolean,
	extension: string,
	// The provider (its program) this is an instance of.
	provider: string,
	/**
	 *  Its id: its refs' segment, its commands' namespace, what
	 *  `activeProviders` names. A provider's default instance has the
	 *  provider's id.
	 */
	instanceId: string,
	capability: string,
	// The project's config enables it.
	enabled: boolean,
	config: unknown,
	// JSON Schema of `config`, from its declarations.
	configSchema: unknown,
	// This machine approved it as it is now.
	approved: boolean,
	// Each credential it declares and where it stands on this machine.
	credentials: InstanceCredential[],
	health: InstanceHealth,
	// Each collector it declares and where its reads stand (P7.A3).
	collectors: CollectorView[],
};

// A kind of provider, as the Settings form offers it.
export type ProviderKindInfo = {
	// What a provider's `kind:` names.
	kind: string,
	title: string,
	// Its API base when a provider names none; `None` when one must.
	defaultBaseUrl: string | null,
};

// A provider's collector a `read` collector runs.
export type ProviderRead = {
	/**
	 *  The instance, `<extension>/<instance id>` (a provider's default
	 *  instance has the provider's id).
	 */
	instance: string,
	collector: string,
};

// One declared provider.
export type ProviderSpec = {
	/**
	 *  The provider's id: its program's approval (`<extension>/<id>`) and
	 *  the id of its default instance — an instance's id is its refs'
	 *  segment (`work_item:<id>:…`) and its commands' namespace
	 *  (`<id>.estimate`).
	 */
	id: string,
	capability: string,
	// The program, relative to the extension folder — or `adapter`.
	entry?: string | null,
	args?: string[],
	// An MCP server run through oxplow's adapter, instead of an `entry`.
	adapter?: AdapterSpec | null,
	// Host environment variables passed through by name.
	env?: string[],
	/**
	 *  Credentials it gets from the keychain, as environment variables:
	 *  each a name (a value the person pastes) or `{ name, oauth }` (one
	 *  they sign in for; the variable holds the access token).
	 */
	credentials?: CredentialDecl[],
	// Hosts it may reach (enforced where the OS can).
	network?: string[],
	// The checked-in `InitializeResult` (JSON), relative to the folder.
	declarations: string,
	/**
	 *  What a work list's own ids look like (a regex matched whole:
	 *  `[A-Z]+-\d+`), so a loose id resolves to its item while it's the
	 *  active work list.
	 */
	idPattern?: string | null,
	/**
	 *  A work list's own fields (kept in an item's `native`), so screens
	 *  render and edit them: `[{ name, title, kind: enum|text|number,
	 *  values? }]`.
	 */
	fields?: FieldDecl[],
	/**
	 *  The scopes it calls over the protocol (`host/call`,
	 *  `sql.read`): part of what its approval covers, and the only ones it
	 *  may call.
	 */
	needs?: string[],
};

// A provider as the UI and agents see it: never its key.
export type ProviderStatus = {
	id: string,
	kind: string,
	baseUrl: string | null,
	keySet: boolean,
};

// What one version's collector made of an input.
export type Ran = {
	// Rows per entity.
	counts: { [key in string]: number },
	// The rows per entity (the first 20).
	rows: unknown,
	/**
	 *  The events it would log, counted per type — as the script
	 *  returned them: whether it may emit them is checked when it runs.
	 */
	events: { [key in string]: number },
	// Why it failed (a model call it tried was refused, say).
	error: string | null,
};

/**
 *  What a query read, as SQLite's authorizer reported it while preparing
 *  it (P4.1).
 */
export type Reads = {
	// Views read, directly or through another view; sorted, distinct.
	models: string[],
	/**
	 *  Tables the query's own SQL read — not through a view (a temp table
	 *  as `temp.<name>`); sorted, distinct. A physical table here is what
	 *  the read contract refuses once enforced (P4.3).
	 */
	tables: string[],
	/**
	 *  Metric measures a `metric_grid()` read (P4.5), filled by the SQL
	 *  gateway; sorted, distinct.
	 */
	measures: string[],
};

// A recent-projects row plus a freshness flag for the UI.
export type RecentProjectView = {
	path: string,
	title: string,
	lastOpenedAt: number,
	/**
	 *  Whether the directory still exists on disk (drives the
	 *  launcher's "missing" badge).
	 */
	exists: boolean,
};

/**
 *  What a report collector records: its parser's typed output, merged
 *  into the run (`.context/collection.md`).
 */
export type Records = 
// A suite/case tree of test outcomes (a `test-run`).
"tests" | 
// Per-file instrumented/covered lines (a coverage capture).
"coverage" | 
// Linter/analyzer findings (a `static-analysis` capture).
"analysis";

/**
 *  A ref kind an extension declares (valid ones; invalid ones are in its
 *  `errors`).
 */
export type RefKindDecl = {
	kind: string,
	extension: string,
	label: string,
	// The anchored regex its ids match.
	idPattern: string,
	// The view whose `title` names one (`v_<extension>_<model>`, by `ref`).
	resolve: string,
	/**
	 *  The page that opens one: `page:ext.<extension>.<page>`, given
	 *  `?ref=<ref>`.
	 */
	page: string,
	wikilink: string | null,
	/**
	 *  The view whose rows (`ref`, `title`, `body`) search indexes under
	 *  the kind (`kind_search`); none, its refs aren't found by search.
	 */
	searchable: string | null,
	icon: string,
	// `file:line` of the declaration.
	declaredAt: string,
};

export type Relationship = {
	column: string,
	// The model the column points into.
	to: string,
	field: string,
};

export type RemoteBranchEntry = {
	ref_name: string,
	short_name: string,
	last_commit_at: number,
	last_commit_subject: string,
};

/**
 *  A report file a collector reads as part of its input
 *  (`input.report`): a tool's output in the worktree.
 */
export type ReportInput = {
	// Relative to the project (`target/type-coverage.json`).
	path: string,
	/**
	 *  How it's parsed before the script sees it: `text` (the default),
	 *  `json`, `xml`, `lcov` or `lines`.
	 */
	format?: string,
};

// How long a namespace's event payloads and large content are kept.
export type RetentionWindow = {
	// Days an event's payload is kept; after it, `{}`.
	payloadDays: number,
	// Days its large content (tool input and output) is kept.
	contentDays: number,
};

// One revision in full: its message and the files it changed.
export type RevisionDetail = {
	info: RevisionInfo,
	body: string,
	files: RevisionFile[],
};

// A file a revision changed, against its first parent.
export type RevisionFile = {
	path: string,
	status: FileStatus,
	additions: number,
	deletions: number,
};

// One revision, as a list shows it.
export type RevisionInfo = {
	id: string,
	short_id: string,
	author: string,
	email: string,
	// Seconds since the Unix epoch.
	time: number,
	subject: string,
	parents: string[],
};

/**
 *  Jobs oxplow gives models. Extensions and features refer to roles,
 *  never to models.
 */
export type Role = "main" | "summarize" | "decide";

export type RoleBinding = {
	// A provider `id`.
	provider: string,
	model: string,
};

export type RoleStatus = {
	role: Role,
	// `None` when the role has no model.
	binding: RoleBinding | null,
	// The binding comes from the project, not the global `ai.yaml`.
	overridden: boolean,
};

// A model's rows before and after.
export type RowDiff = {
	// Rows on each side (`None`: it isn't on that side).
	before: number | null,
	after: number | null,
	// Row by row, when both sides declare the same key.
	keyed: KeyedDiff | null,
	// Why the diff is only counts, or that a side's query failed.
	note: string | null,
};

export type RowSample = {
	change: Change,
	// The row's key, column → value.
	key: unknown,
	before: unknown | null,
	after: unknown | null,
};

// The kind of run a report collector reads after.
export type RunKind = "test" | "analysis";

// Whose an instance is (P9.B2).
export type Scope = 
/**
 *  The project's: in its `extensionInstances`, shared with the team;
 *  its credentials are this project's on this machine.
 */
"project" | 
/**
 *  The person's: in this machine's `instances.yaml`, running in every
 *  project that has its extension; its credentials are set once.
 */
"global";

/**
 *  One ranked search result. `stream_id` is `None` for project-global
 *  entities (wiki pages); `score` is the BM25 score (lower = better match).
 */
export type SearchHit = {
	kind: string,
	ref_id: string,
	stream_id: string | null,
	title: string,
	snippet: string,
	score: number,
};

export type SelectThreadRequest = {
	streamId: StreamId,
	threadId: ThreadId | null,
};

/**
 *  Who the extension is for. Explicit and checked: a shared extension
 *  (committed for a team, installed from git, bundled) may use stable
 *  kinds only and must name the engine it targets.
 */
export type Sharing = "private" | "shared";

// How handing a redirect to a sign-in went (`complete_oauth_sign_in`).
export type SignInCompletion = 
// Signed in: the token is kept and the instance restarts on it.
{ outcome: "signed_in" } | 
/**
 *  The sign-in ended without a token: why (what `CredentialChanged`
 *  carries too).
 */
{ outcome: "failed"; error: string } | 
/**
 *  Not this sign-in's redirect (another `state`, another path):
 *  nothing was done, and the sign-in still waits.
 */
{ outcome: "not_this_sign_in"; reason: string };

// Where a signed-in credential stands on this machine.
export type SignInState = { state: "not_signed_in" } | 
/**
 *  `until` (RFC 3339): when it lapses, for one that can't renew
 *  itself; none, it lasts until the service refuses it.
 */
{ state: "signed_in"; until: string | null } | 
// Its token lapsed or was revoked, and it can't renew itself.
{ state: "sign_in_again" };

// One skill or command as the extension declares it.
export type SkillDecl = {
	name: string,
	kind: SkillKind,
	// Its markdown, inside the extension.
	file: string,
	// What it needs active (`work_items`, `work_items.comments`).
	needs: string[],
};

// What the agent's runtime makes of it.
export type SkillKind = 
// A skill the agent loads when it's relevant: `<name>/SKILL.md`.
"skill" | 
// A slash command the person runs: `/oxplow:<name>`.
"command";

/**
 *  `snapshot` row — one per `request_snapshot()` call that had
 *  dirty files. Groups the `file_snapshot` rows captured in that
 *  batch. See [[crates/oxplow-db/migrations/V13__snapshot.sql]].
 */
export type Snapshot = {
	id: number,
	stream_id: StreamId,
	created_at: Timestamp,
	file_count: number,
	/**
	 *  The VCS revision this snapshot's tree equals (`git:<sha>`).
	 *  Populated only when the workspace was clean at the head at
	 *  capture time; `None` when it was dirty or isn't under version
	 *  control. Not unique — several snapshots can share one revision
	 *  when local history captures files the VCS doesn't track.
	 */
	revision: string | null,
	/**
	 *  The branch the workspace was on when this snapshot was captured
	 *  (e.g. `main`). `None` for pre-V42 rows, a detached head, or a
	 *  directory not under version control.
	 */
	branch: string | null,
	/**
	 *  Whole-tree identity (V96): the xxh3-128 of the sorted manifest of
	 *  the reconstructed tree ([`crate::snapshot_tree::manifest_hash`]).
	 *  Two snapshots with equal `tree_hash` hold the same files. `None`
	 *  on snapshots taken before V96.
	 */
	tree_hash: string | null,
	/**
	 *  What the take that CREATED this snapshot recorded (its first
	 *  `snapshot_op`, P2.11): the snapshot it grew from — the "previous"
	 *  a single-snapshot diff starts at — why it was taken, and whether
	 *  it ran over its budget. `None` / `false` for a snapshot with no op.
	 */
	parent_snapshot_id: number | null,
	trigger: SnapshotTrigger | null,
	over_budget: boolean,
};

// One row of the operation log (`snapshot_op`).
export type SnapshotOp = {
	seq: number,
	stream_id: StreamId,
	snapshot_id: number,
	parent_snapshot_id: number | null,
	trigger: SnapshotTrigger,
	thread_id: ThreadId | null,
	turn_id: number | null,
	effort_id: EffortId | null,
	at: Timestamp,
	elapsed_ms: number,
	budget_ms: number | null,
	over_budget: boolean,
	file_count: number,
	// What took it; `None` for ops recorded before V45.
	provider: string | null,
	// Whether the take kept file contents (`false`: hashes only).
	contents: boolean,
	/**
	 *  The provider's name for the state it marked (V46); `None` for a take
	 *  by core's capture pipeline.
	 */
	handle: string | null,
};

/**
 *  Aggregate created/modified/deleted counts for the file rows
 *  captured under one snapshot. Derived by comparing each child
 *  row's `blob_hash` to the most-recent prior row for the same
 *  `(stream_id, path)`. Powers the Local History dashboard's
 *  per-snapshot stats column.
 */
export type SnapshotStats = {
	created: number,
	modified: number,
	deleted: number,
	total: number,
};

/**
 *  Where a captured file's bytes live — the explicit `file_snapshot.storage`
 *  discriminator (V37). Replaces the old implicit `(blob_hash NULL?,
 *  oversize?)` 2-bit encoding. The `blob_hash` column means different
 *  things per variant:
 *  - [`Oxplow`](SnapshotStorage::Oxplow): `blob_hash` is an xxh3-128, bytes
 *    in `.oxplow/snapshots/objects/`.
 *  - [`Git`](SnapshotStorage::Git): `blob_hash` is a **git blob OID**, bytes
 *    recovered on demand from the git object db (`git cat-file` / libgit2
 *    `find_blob`). The capture path never copied them — a clean checkout
 *    reuses git's own storage.
 *  - [`Oversize`](SnapshotStorage::Oversize): `blob_hash` is NULL; the file
 *    was too big to hash, only `size_bytes` + `mtime_ms` are tracked.
 *  - [`Deleted`](SnapshotStorage::Deleted): `blob_hash` is NULL; a tombstone
 *    row marking the path gone as of this snapshot.
 */
export type SnapshotStorage = "oxplow" | "git" | "oversize" | "deleted";

/**
 *  Why a snapshot take happened: one row of the operation log each
 *  (`snapshot_op.trigger`) and the `trigger` of `snapshot.taken`.
 */
export type SnapshotTrigger = 
// An agent turn ended (Stop / interrupt).
"turn_end" | 
// The worktree went quiet with no turn open (human edits).
"quiet" | 
// An effort opened (its start bracket).
"effort_start" | 
/**
 *  An effort closed (its end bracket), including a restart closing
 *  an orphaned effort.
 */
"effort_end" | 
// The boot sweep.
"startup" | 
// An explicit request (metric baseline rebuild, tests).
"manual" | 
// HEAD or a ref moved; the take drains whatever was dirty.
"git_refs" | 
/**
 *  HEAD moved on a clean tree: the latest snapshot now also is the
 *  new commit (a re-stamp, no new snapshot).
 */
"head_moved" | 
/**
 *  A run's reports were recorded (coverage, analysis): the code it
 *  measured, which their captures are pinned to (tsk883).
 */
"run_measured" | 
// Backfilled for a snapshot taken before the operation log existed.
"legacy";

/**
 *  One SQL value, serialized as a plain JSON scalar (`null`, boolean,
 *  number or string) so the TS binding is `null | boolean | number |
 *  string` rather than serde_json's tagged-enum shape.
 */
export type SqlCell = null | boolean | number | string;

/**
 *  Result of a read-only SQL query. `rows` are positional, aligned with
 *  `columns`. `truncated` is true when more rows existed than the cap.
 */
export type SqlQueryResult = {
	columns: string[],
	rows: SqlCell[][],
	truncated: boolean,
	// What the query read — what a caller subscribes to (P4.6).
	reads: Reads,
	/**
	 *  When each model it read last changed since the app started (the
	 *  SQL gateway fills it, P4.6); a model unchanged since then is absent.
	 */
	freshness: ModelFreshness[],
};

// One changed path in a workspace.
export type StatusEntry = {
	path: string,
	status: FileStatus,
};

// An envelope as read back from the log, with its position.
export type StoredEvent = {
	// Global insert order; the delivery order and what checkpoints hold.
	seq: number,
	/**
	 *  When retention replaced the payload with `{}` (the envelope stays).
	 *  An expired event is history only: the pump skips it and nothing
	 *  derives state from it.
	 */
	payload_expired_at: Timestamp | null,
} & (Envelope);

export type Stream = {
	id: StreamId,
	kind: StreamKind,
	title: string,
	branch: string,
	branch_ref: string,
	branch_source: string,
	worktree_path: string,
	working_pane: string,
	talking_pane: string,
	working_session_id: string,
	talking_session_id: string,
	// The host its worktree is on.
	host: HostId,
	/**
	 *  Standing instructions appended to every agent system prompt
	 *  when this stream is active. `None` (or empty) clears it.
	 */
	custom_prompt: string | null,
	created_at: Timestamp,
	updated_at: Timestamp,
	/**
	 *  Set when the stream was archived via the rail's "Remove…"
	 *  action. Archived streams are filtered out of `StreamStore::list`
	 *  so they disappear from the rail; the row stays in the DB so
	 *  history references (efforts, snapshots, page_visit) don't
	 *  dangle.
	 */
	archived_at: Timestamp | null,
};

export type StreamId = string;

// Whether a stream is the project's primary stream or a worktree.
export type StreamKind = "primary" | "worktree";

/**
 *  One declared test, written as a one-key map: `{ not_null: id }`,
 *  `{ unique: id }`, `{ accepted_values: { column, values } }`,
 *  `{ relationships: { column, to, field } }` or `{ sql: "SELECT …" }` (a
 *  query returning the failing rows).
 */
export type TestDecl = {
	not_null?: string | null,
	unique?: string | null,
	accepted_values?: AcceptedValues | null,
	relationships?: Relationship | null,
	sql?: string | null,
};

/**
 *  How this project's tests run (the `testing:` block), written by
 *  `/oxplow:configure`. The Bash-hook detector reads the commands and
 *  patterns to tell a test or analysis run; what such a run's reports hold
 *  is read by the report collectors (`collectors:` with `records:`, see
 *  [`collectors::Records`]). All optional.
 */
export type TestingConfig = {
	/**
	 *  The command that runs the project's tests and writes their reports
	 *  (counts as a test run; named in the report-less nudge).
	 */
	command: string | null,
	/**
	 *  The coverage-free counterpart to `command`, for the red/green loop
	 *  (tsk171). It still writes a test report (JUnit), so the
	 *  progression lands in the effort's Tests panel, but skips coverage
	 *  and should accept a filter.
	 * 
	 *  This exists because the alternative is worse. When the only
	 *  report-emitting command is a full instrumented run of the whole
	 *  suite, "route every invocation through it" is unfollowable in a TDD
	 *  loop, so it gets dropped — and then NONE of the red→green runs are
	 *  recorded. A weaker rule that is actually followed beats a stricter
	 *  one that isn't.
	 */
	fastCommand: string | null,
	/**
	 *  Extra command substrings that count as a test run, on top of the
	 *  built-in defaults (pytest, cargo test, jest, …).
	 */
	runPatterns: string[],
	/**
	 *  Extra command substrings that count as a static-analysis run, on
	 *  top of the built-in defaults (cargo clippy, eslint, ruff, …).
	 */
	analysisPatterns: string[],
	/**
	 *  Free-form hint injected verbatim into every agent system prompt:
	 *  which test command to run, what coverage to meet, and so on.
	 */
	agentHint: string | null,
};

// A line of a workspace file that matched a text search.
export type TextSearchHit = {
	path: string,
	// 1-based.
	line: number,
	// The line, cut at 400 bytes.
	snippet: string,
};

export type Thread = {
	id: ThreadId,
	stream_id: StreamId,
	title: string,
	status: ThreadStatus,
	sort_index: number,
	summary: string,
	summary_updated_at: Timestamp | null,
	/**
	 *  Timestamp when the thread was closed (status transitions to
	 *  `Closed`). `None` for active/queued threads.
	 */
	closed_at: Timestamp | null,
	/**
	 *  Per-thread custom prompt appended to the agent's system message.
	 *  `None` when unset; `Some("")` is distinct (empty override).
	 */
	custom_prompt: string | null,
	created_at: Timestamp,
	updated_at: Timestamp,
	/**
	 *  Set when the thread was archived as part of its stream's
	 *  "Remove…" action. Archived threads are filtered out of
	 *  `ThreadStore::list_for_stream`.
	 */
	archived_at: Timestamp | null,
};

export type ThreadId = string;

/**
 *  A note on a thread: the per-thread capture pad an agent writes as it
 *  works (`oxplow.knowledge.add_note`). Its ref is `thread_note:not<n>`.
 */
export type ThreadNote = {
	id: NoteId,
	thread_id: ThreadId,
	body: string,
	author: string,
	created_at: Timestamp,
};

export type ThreadState = {
	selectedThreadId: ThreadId | null,
	activeThreadId: ThreadId | null,
	threads: Thread[],
};

/**
 *  Thread lifecycle status — mirrors the TS `ThreadState` shape.
 * 
 *  `Active` is the writer thread for its stream (only one per stream
 *  can mutate the worktree at a time). `Queued` is a non-writer
 *  thread sharing the same worktree in read-only mode. `Closed` is
 *  terminated; closed threads are excluded from the rail.
 */
export type ThreadStatus = "active" | "queued" | "closed";

// Wall-clock UTC timestamp serialized as a fixed-width RFC 3339 string.
export type Timestamp = string;

/**
 *  A tool call as last reported: the initial `tool_call` with every
 *  `tool_call_update` for its id applied.
 */
export type ToolCall = {
	id: string,
	title: string,
	// The agent's programmatic tool name, when it sends one.
	name: string | null,
	kind: ToolKind,
	status: ToolStatus,
	// Paths from `locations` (absolute, per the protocol).
	locations: string[],
	// The agent's own JSON for the call; `unknown` to the renderer.
	rawInput: unknown | null,
	rawOutput: unknown | null,
	diffs: ToolDiff[],
	// Text content blocks (command output, messages).
	text: string[],
};

/**
 *  What the agent policy decided about a tool call (PreToolUse), carried
 *  on the envelope so the log records it.
 */
export type ToolDecision = {
	allowed: boolean,
	reason: string | null,
};

// One file change a tool call reports. `old_text: None` means a new file.
export type ToolDiff = {
	path: string,
	oldText: string | null,
	newText: string,
};

// The ACP tool categories, mirrored so the SDK's enum stays in `wire.rs`.
export type ToolKind = "read" | "edit" | "delete" | "move" | "search" | "execute" | "think" | "fetch" | "switch_mode" | "other";

export type ToolStatus = "pending" | "in_progress" | "completed" | "failed";

export type TranscriptItem = {
	id: number,
	seq: number,
} & (ItemBody);

// When a collector runs by itself.
export type Trigger = 
// Only when someone runs it (`oxplow.collector.sync`).
{ kind: "manual" } | 
// Every `minutes` minutes (an exec collector once approved).
{ kind: "every"; minutes: number } | 
/**
 *  When an event of one of these types is logged and its payload has
 *  each `filter` field equal to its value — after the consumers in
 *  the collector's `after` have handled the event.
 */
{ kind: "on"; events: string[]; filter: { [key in string]: string }; 
/**
 *  When the run happens after a triggering event: at
 *  once by default.
 */
pacing?: Pacing } | 
/**
 *  A report collector's: when the agent runs the project's tests or an
 *  analyzer (the `collection` reactor detects the run), if its report
 *  was written by that run.
 */
{ kind: "onRun"; run: RunKind };

// What a kept earlier version is a version of.
export type Twin = {
	// The model's name.
	of: string,
	until: string,
};

// A decorator (valid ones; invalid ones are in the extension's `errors`).
export type UiDecorator = {
	// `<extension>/<n>`.
	id: string,
	extension: string,
	// The model's view (`v_<extension>_<model>`), which has a `ref` column.
	view: string,
	// The ref kind it decorates (`work_item`).
	kind: string,
	placement: DecoratorPlacement,
	// The view's column holding the text shown.
	label: string,
	// The view's column holding a color (`#rrggbb` or a CSS color name).
	color: string | null,
};

export type UiLogEntry = {
	clientId: string | null,
	level: string,
	message: string,
	/**
	 *  JSON-encoded structured context (the renderer stringifies its
	 *  own object so the boundary is plain `Option<String>`).
	 */
	context: string | null,
	timestamp: string | null,
};

/**
 *  A replacement (valid ones; invalid ones are in the extension's
 *  `errors`).
 */
export type UiReplacement = {
	// `<extension>/<target>`.
	id: string,
	extension: string,
	// The core sub-component it replaces (`work_item.board`).
	target: string,
	/**
	 *  The capability whose active provider must be this extension's for
	 *  it to render.
	 */
	capability: string,
	// The lens that renders instead, given the target's props.
	lensId: string,
	// What a person calls the target (`board`), from its table.
	label: string,
};

export type UsageEvent = {
	id: string,
	kind: string,
	payload_json: string,
	occurred_at: Timestamp,
};

/**
 *  Per-key aggregation of usage events. Returned by
 *  `SqliteUsageStore::list_recent_rollup` for callers that want
 *  "most-recently-touched X" lists rather than the raw event log
 *  (e.g. the WikiActivityBar's recent-files strip).
 */
export type UsageRollup = {
	kind: string,
	key: string,
	last_at: Timestamp,
	count: number,
};

// One working copy of the repository (feature `isolated_workspaces`).
export type VcsWorkspace = {
	path: string,
	branch: string | null,
	head: string | null,
	// The repository's primary working copy.
	is_main: boolean,
};

export type VisitedPage = {
	page_kind: string,
	page_id: string,
	visit_count: number,
};

// What a provider supports beyond create, update and transition.
export type WorkItemsFeatures = {
	// Items nest (a parent ref).
	hierarchy: boolean,
	comments: boolean,
	links: boolean,
	// Items can be deleted (`oxplow.work_item.delete`).
	delete?: boolean,
	/**
	 *  A write sent twice with one idempotency key is done once, the
	 *  second answered as the first (the protocol's
	 *  `InvokeParams.idempotency_key`): the host may send a write again
	 *  when its reply was lost.
	 */
	idempotent_writes?: boolean,
	/**
	 *  Items have an order on their list (`oxplow.work_item.reorder`; read as
	 *  `v_work_item.rank`).
	 */
	ordering?: boolean,
	/**
	 *  Items are on a thread's list or the backlog, and move between them
	 *  (`oxplow.work_item.move`; read as `v_work_item.thread_id`).
	 */
	lists?: boolean,
};

/**
 *  fs-watch classification mirrored onto the wire so the renderer can
 *  distinguish create / modify / delete / rename without re-stating
 *  every variant of the upstream `notify` crate.
 */
export type WorkspaceChangeKind = "created" | "updated" | "deleted" | "renamed";

export type WorkspaceContext = {
	project_dir: string,
	default_branch: string | null,
	vcs_enabled: boolean,
};

export type WorkspaceEntry = {
	name: string,
	path: string,
	kind: WorkspaceEntryKind,
	status: FileStatus | null,
	hasChanges: boolean,
};

export type WorkspaceEntryKind = "file" | "directory";

export type WorkspaceFile = {
	path: string,
	content: string,
};

export type WorkspaceIndexedFile = {
	path: string,
	status: FileStatus | null,
};

// A workspace's changes against its head.
export type WorkspaceStatus = {
	// Changed paths, sorted.
	entries: StatusEntry[],
	// The operation in progress, if one is.
	in_progress: InProgressOp | null,
};

/**
 *  One row of the project's `zones:` table: the globs that select files
 *  and the zone label they belong to.
 * 
 *  Zones are entirely project-defined (tsk251) — oxplow ships no rule
 *  table of its own, because a file's architectural role follows from
 *  how *this* project lays out its repo. Order in the table is
 *  load-bearing: [`ZoneRules`](../oxplow_code_deps/zones/struct.ZoneRules.html)
 *  takes the FIRST matching rule, so specific patterns must precede
 *  catch-alls.
 */
export type ZoneRuleConfig = {
	/**
	 *  Globs selecting the files in this zone (any-of). In YAML `match`
	 *  accepts a single string or a list; both land here as a list.
	 *  Matched against the full repo-relative path with `*` stopping at
	 *  `/` — `**` is the only way to span directories.
	 */
	match: string[],
	// The zone label. Free-form; `other` and `external` are reserved.
	zone: string,
	/**
	 *  Optional display colour (`#rrggbb` or `#rgb`). The first rule to
	 *  name a label wins; labels with no colour get a palette entry
	 *  assigned by order of first appearance.
	 */
	color?: string | null,
};

/* Tauri Specta runtime */
async function typedError<T, E>(result: Promise<T>): Promise<{ status: "ok"; data: T } | { status: "error"; error: E }> {
    try {
        return { status: "ok", data: await result };
    } catch (e) {
        if (e instanceof Error) throw e;
        return { status: "error", error: e as any };
    }
}

